<template>
  <ion-page>
    <div class="portal-shell">
      <aside class="sidebar">
        <div class="brand"><span class="brand-icon"><ion-icon :icon="shirtOutline" /></span><div><b>UniformHub</b><small>PHINMA Services</small></div></div>
        <p class="menu-label">MAIN MENU</p>
        <nav><router-link v-for="item in menu" :key="item.path" :to="`/${role}/${item.path}`" :class="{active:section===item.path}"><ion-icon :icon="item.icon" />{{item.label}}</router-link></nav>
        <div class="account" style="grid-template-columns:38px 1fr"><span>{{initials}}</span><div><b>{{portal.user.value?.name}}</b><small>{{role==='marketing'?'Marketing Office':portal.user.value?.identifier}}</small></div></div>
      </aside>
      <main class="portal-main">
        <header class="topbar"><button class="mobile-menu" @click="navOpen=!navOpen"><ion-icon :icon="menuOutline" /></button><b>{{pageTitle}}</b><div class="topbar-actions"><button class="notification-button" title="Notifications"><ion-icon :icon="notificationsOutline"/></button><div class="account-menu-wrap" @keydown.esc="accountMenuOpen=false"><button class="avatar-button" :aria-expanded="accountMenuOpen" aria-haspopup="menu" title="Open account menu" @click="accountMenuOpen=!accountMenuOpen"><span class="avatar">{{initials}}</span><ion-icon :icon="chevronDownOutline"/></button><div v-if="accountMenuOpen" class="account-menu" role="menu"><div class="account-menu-head"><span class="avatar">{{initials}}</span><div><b>{{portal.user.value?.name}}</b><small>{{role==='marketing'?'Marketing Office':portal.user.value?.identifier}}</small></div></div><router-link :to="`/${role}/profile`" role="menuitem" @click="accountMenuOpen=false"><ion-icon :icon="personCircleOutline"/><span><b>Profile</b><small>View and edit your information</small></span></router-link><router-link :to="`/${role}/settings`" role="menuitem" @click="accountMenuOpen=false"><ion-icon :icon="settingsOutline"/><span><b>Settings</b><small>Password and account security</small></span></router-link><button class="menu-signout" role="menuitem" @click="logout"><ion-icon :icon="logOutOutline"/><span><b>Sign out</b><small>End this session</small></span></button></div></div></div></header><button v-if="accountMenuOpen" class="account-menu-scrim" aria-label="Close account menu" @click="accountMenuOpen=false"></button>
        <div v-if="navOpen" class="mobile-nav"><router-link v-for="item in menu" :key="item.path" :to="`/${role}/${item.path}`" @click="navOpen=false">{{item.label}}</router-link></div>
        <ion-content class="content"><div class="page-container">
          <div v-if="busy" class="loading-line">Loading portal data…</div>
          <p v-if="message" :class="['flash',messageType]">{{message}}</p>

          <section v-if="section==='dashboard'">
            <div class="page-head"><div><p class="kicker">{{role==='marketing'?'MARKETING OFFICE':'STUDENT PORTAL'}}</p><h1>Welcome, {{firstName}}</h1><p>{{role==='marketing'?'Manage uniform requests, inventory, and student records.':'Request school uniforms and follow their status.'}}</p></div></div>
            <div class="stats"><article><ion-icon :icon="documentTextOutline"/><div><b>{{portal.requests.value.length}}</b><span>Total requests</span></div></article><article><ion-icon :icon="timeOutline"/><div><b>{{pendingCount}}</b><span>Pending</span></div></article><article><ion-icon :icon="checkmarkCircleOutline"/><div><b>{{readyCount}}</b><span>Ready / completed</span></div></article><article v-if="role==='marketing'"><ion-icon :icon="cubeOutline"/><div><b>{{totalStock}}</b><span>Items in stock</span></div></article></div>
            <section class="card"><div class="card-head"><div><h2>Recent requests</h2><p>Latest uniform request activity</p></div><router-link :to="`/${role}/requests`">View all</router-link></div><RequestTable :rows="portal.requests.value.slice(0,5)" @select="selectedRequest=$event"/></section>
          </section>

          <section v-else-if="section==='catalog'">
            <div class="page-head"><div><p class="kicker">UNIFORM REQUEST</p><h1>Available uniforms</h1><p>Select a uniform and size. Pickup is at the school only.</p></div><ion-button @click="cartOpen=true" :disabled="cart.length===0"><ion-icon slot="start" :icon="bagHandleOutline"/>Request ({{cart.length}})</ion-button></div>
            <div class="product-grid"><article v-for="product in portal.products.value" :key="product.id" class="product-card"><div class="product-art"><ion-icon :icon="shirtOutline"/></div><p class="kicker">{{product.category}}</p><h2>{{product.name}}</h2><p>{{product.description}}</p><label>Size</label><select v-model="chosen[product.id]"><option value="">Select size</option><option v-for="s in product.sizes" :key="s.id" :value="s.id" :disabled="s.stock<1">{{s.label}} — {{s.stock}} available</option></select><ion-button expand="block" :disabled="!chosen[product.id]" @click="addToCart(product)">Add to request</ion-button></article></div>
            <div v-if="!portal.products.value.length" class="card empty-state"><ion-icon :icon="shirtOutline"/><h2>No uniforms available</h2><p>Please check again later.</p></div>
          </section>

          <section v-else-if="section==='requests'">
            <div class="page-head requests-head"><div><p class="kicker">{{role==='marketing'?'MANAGE REQUESTS':'MY REQUESTS'}}</p><h1>Uniform requests</h1><p>Review request details and keep every request moving.</p></div><span class="request-total"><b>{{filteredRequests.length}}</b> shown</span></div>
            <div class="request-summary"><button :class="{active:status===''}" @click="status=''">All requests <b>{{portal.requests.value.length}}</b></button><button :class="{active:status==='Pending'}" @click="status='Pending'">Pending <b>{{statusCount('Pending')}}</b></button><button :class="{active:status==='Approved'}" @click="status='Approved'">Approved <b>{{statusCount('Approved')}}</b></button><button :class="{active:status==='Ready for Pickup'}" @click="status='Ready for Pickup'">Ready <b>{{statusCount('Ready for Pickup')}}</b></button></div>
            <div class="filters request-filters"><ion-searchbar v-model="search" placeholder="Search reference, student name, or ID"/><label><span>Status</span><select v-model="status"><option value="">All statuses</option><option v-for="s in statuses" :key="s">{{s}}</option></select></label></div>
            <section class="card requests-card"><div class="table-heading"><div><h2>Request list</h2><p>{{filteredRequests.length}} of {{portal.requests.value.length}} requests</p></div><button v-if="search||status" @click="search='';status=''">Clear filters</button></div><RequestTable :rows="filteredRequests" @select="selectedRequest=$event"/></section>
          </section>

          <section v-else-if="section==='students' && role==='marketing'" class="student-directory">
            <div class="page-head"><div><p class="kicker">STUDENT DIRECTORY</p><h1>Student directory</h1><p>View student accounts or share a reusable registration link.</p></div><div class="head-actions"><button class="outline-button" @click="generateInvite('student')">Generate student invite</button><a class="outline-button" href="/assets/student-account-import-template.xlsx" download>Download Excel template</a></div></div>
            <div v-if="studentInviteLink" class="generated-link directory-link"><b>Reusable student registration link</b><div><input :value="studentInviteLink" readonly/><button type="button" @click="copyInvite(studentInviteLink)">Copy</button></div><small>Multiple students can register until this link expires or is revoked.</small></div>
            <div v-if="studentInvites.length" class="student-invite-list"><article v-for="invite in studentInvites" :key="invite.id"><div><b>Student registration link</b><span>{{invite.usageCount}} account(s) registered · Expires {{formatInviteDate(invite.expiresAt)}}</span></div><em :class="inviteStatus(invite).toLowerCase()">{{inviteStatus(invite)}}</em><button v-if="inviteStatus(invite)==='Active'" @click="revokeInvitation(invite.id)">Revoke</button><button @click="deleteInvitation(invite.id)">Remove</button></article></div>
            <div class="info-strip"><b>Directory import</b><span>Imported rows are saved in this browser and displayed immediately.</span></div>
            <div class="filters"><ion-searchbar v-model="studentSearch" placeholder="Search name, Student ID, or email"/></div>
            <section class="card table-wrap"><table><thead><tr><th>Student</th><th>Student ID</th><th>PHINMA email</th><th>Program</th><th>Year</th></tr></thead><tbody><tr v-for="s in filteredStudents" :key="s.id"><td><b>{{s.fullName}}</b></td><td>{{s.studentId}}</td><td>{{s.phinmaEmail}}</td><td>{{s.program||'—'}}</td><td>{{s.year||'—'}}</td></tr><tr v-if="!filteredStudents.length"><td colspan="5" class="empty">No students found.</td></tr></tbody></table></section>
          </section>

          <section v-else-if="section==='inventory' && role==='marketing'">
            <div class="page-head"><div><p class="kicker">INVENTORY</p><h1>Uniform inventory</h1><p>Add uniforms and sizes, then manage available stock quantities.</p></div><div class="head-actions"><button class="outline-button" @click="printReport"><ion-icon :icon="documentOutline"/> Export PDF</button><ion-button @click="openInventory()"><ion-icon slot="start" :icon="addCircleOutline"/>Add uniform or size</ion-button></div></div>
            <div v-if="portal.products.value.length" class="inventory-grid"><article v-for="p in portal.products.value" :key="p.id" class="card inventory-card"><div class="inventory-title"><ion-icon :icon="shirtOutline"/><div><p class="kicker">{{p.category}}</p><h2>{{p.name}}</h2><p>{{p.description}}</p></div><button @click="openInventory(p)">Add size</button></div><div class="sizes"><div v-for="s in p.sizes" :key="s.id"><b>{{s.label}}</b><span>{{s.stock}} in stock</span><div><button @click="changeStock(s.id,-1)">−</button><button @click="changeStock(s.id,1)">+</button></div></div></div></article></div>
            <div v-else class="card empty-inventory"><ion-icon :icon="cubeOutline"/><h2>No uniforms yet</h2><p>Add the first uniform, size, and stock quantity.</p><ion-button @click="openInventory()">Add inventory</ion-button></div>
          </section>

          <section v-else-if="section==='staff' && role==='marketing'">
            <div class="page-head"><div><p class="kicker">STAFF ACCESS</p><h1>Marketing invitations</h1><p>Create secure, expiring registration links for authorized Marketing Office staff.</p></div></div>
            <div class="staff-layout"><form class="card invite-form" @submit.prevent="generateInvite('marketing')"><div><h2>Generate shared link</h2><p>Multiple authorized staff can register before the link expires.</p></div><label>Link expires in<select v-model.number="inviteHours"><option :value="1">1 hour</option><option :value="24">24 hours</option><option :value="72">3 days</option><option :value="168">7 days</option><option :value="720">30 days</option></select></label><ion-button type="submit" :disabled="saving">{{saving?'Generating…':'Generate staff link'}}</ion-button><div v-if="staffInviteLink" class="generated-link"><b>Reusable staff registration link</b><div><input :value="staffInviteLink" readonly/><button type="button" @click="copyInvite(staffInviteLink)">Copy</button></div><small>Share securely. Anyone with this link can create a Marketing account until it expires or is revoked.</small></div></form><section class="card invitations-list"><div class="table-heading"><div><h2>Registration links</h2><p>Revoke or remove links at any time.</p></div></div><div v-if="!marketingInvites.length" class="invite-empty">No staff invitation links yet.</div><article v-for="invite in marketingInvites" :key="invite.id" class="invite-row"><div><b>Marketing registration link</b><span>{{invite.usageCount}} account(s) registered</span><small>Expires {{formatInviteDate(invite.expiresAt)}}</small></div><span :class="['invite-status',inviteStatus(invite).toLowerCase()]">{{inviteStatus(invite)}}</span><div class="invite-actions"><button v-if="inviteStatus(invite)==='Active'" @click="revokeInvitation(invite.id)">Revoke</button><button class="danger-button" @click="deleteInvitation(invite.id)">Remove</button></div></article></section></div>
          </section>

          <section v-else-if="section==='profile'">
            <div class="page-head"><div><p class="kicker">MY PROFILE</p><h1>Profile information</h1><p>Review and update your personal account details.</p></div></div>
            <div class="profile-single"><form class="card form-card" @submit.prevent="saveProfile"><div class="form-title"><span class="profile-avatar-small">{{initials}}</span><div><h2>Personal information</h2><p>Keep your school account information accurate.</p></div></div><label>Full name<input v-model="profile.name" required/></label><label>{{role==='student'?'Student ID':'Employee ID'}}<input v-model="profile.identifier" required/></label><label>Email<input v-model="profile.email" type="email"/></label><label>Phone<input v-model="profile.phone"/></label><template v-if="role==='student'"><label>Program<input v-model="profile.program"/></label><label>Year level<select v-model="profile.year"><option value="" disabled>Select year level</option><option value="1st Year">1st Year</option><option value="2nd Year">2nd Year</option><option value="3rd Year">3rd Year</option><option value="4th Year">4th Year</option><option value="5th Year">5th Year</option><option value="Graduate">Graduate</option></select></label></template><div class="form-actions"><ion-button type="submit" :disabled="saving">{{saving?'Saving…':'Save profile'}}</ion-button></div></form></div>
          </section>

          <section v-else-if="section==='settings'">
            <div class="page-head"><div><p class="kicker">ACCOUNT SETTINGS</p><h1>Password and security</h1><p>Choose a strong password to protect your account.</p></div></div>
            <div class="profile-single settings-page"><form class="card form-card" @submit.prevent="savePassword"><div class="form-title"><span class="settings-icon"><ion-icon :icon="settingsOutline"/></span><div><h2>Change password</h2><p>Verify your current password, then choose a new password with at least 8 characters.</p></div></div><label class="current-password">Current password<input v-model="currentPassword" type="password" autocomplete="current-password" required/></label><label>New password<input v-model="newPassword" type="password" minlength="8" autocomplete="new-password" required/></label><label>Confirm new password<input v-model="confirmPassword" type="password" minlength="8" autocomplete="new-password" required/></label><div class="security-note"><ion-icon :icon="shieldCheckmarkOutline"/><span>After changing your password, use the new password the next time you sign in.</span></div><div class="form-actions"><ion-button type="submit" :disabled="saving||!currentPassword||newPassword.length<8||confirmPassword.length<8">{{saving?'Updating…':'Update password'}}</ion-button></div></form></div>
          </section>
        </div></ion-content>
      </main>
    </div>

    <div v-if="selectedRequest" class="modal-backdrop" @click.self="selectedRequest=null"><section class="modal-card"><button class="close" @click="selectedRequest=null">×</button><p class="kicker">REQUEST DETAILS</p><h2>{{selectedRequest.reference}}</h2><p><b>{{selectedRequest.studentName}}</b> · {{selectedRequest.studentId}}</p><span class="status-pill">{{selectedRequest.status}}</span><div class="request-items"><div v-for="i in selectedRequest.items" :key="i.sizeId"><span>{{i.productName}} — {{i.size}}</span><b>× {{i.quantity}}</b></div></div><p><b>Pickup:</b> School campus</p><div v-if="role==='marketing'" class="modal-actions"><ion-button v-for="s in nextStatuses(selectedRequest.status)" :key="s" @click="setStatus(s)">{{s}}</ion-button></div></section></div>
    <div v-if="inventoryOpen" class="modal-backdrop" @click.self="inventoryOpen=false"><form class="modal-card inventory-modal" @submit.prevent="saveInventory"><button type="button" class="close" @click="inventoryOpen=false">×</button><p class="kicker">INVENTORY ENTRY</p><h2>Add uniform stock</h2><label>Uniform<select v-model="inventory.productId" @change="pickProduct"><option value="">Create a new uniform</option><option v-for="p in portal.products.value" :value="p.id" :key="p.id">{{p.name}}</option></select></label><label>Uniform name<input v-model="inventory.name" required :disabled="!!inventory.productId"/></label><label>Category<input v-model="inventory.category" required :disabled="!!inventory.productId"/></label><label>Description<textarea v-model="inventory.description" :disabled="!!inventory.productId" placeholder="Short uniform description"/></label><div class="two-cols"><label>Size<input v-model="inventory.size" placeholder="e.g. S, M, L, XL" required/></label><label>Initial stock<input v-model.number="inventory.stock" type="number" min="0" required/></label></div><ion-button expand="block" type="submit" :disabled="saving">{{saving?'Saving…':'Save inventory'}}</ion-button></form></div>
    <div v-if="cartOpen" class="modal-backdrop" @click.self="cartOpen=false"><section class="modal-card"><button class="close" @click="cartOpen=false">×</button><p class="kicker">REQUEST SUMMARY</p><h2>Your uniform request</h2><div class="request-items"><div v-for="(i,n) in cart" :key="i.sizeId"><span>{{i.productName}} — {{i.size}}</span><span><button @click="i.quantity=Math.max(1,i.quantity-1)">−</button> {{i.quantity}} <button @click="i.quantity++">+</button> <button @click="cart.splice(n,1)">Remove</button></span></div></div><p><b>Pickup location:</b> School campus</p><ion-button expand="block" :disabled="saving||!cart.length" @click="submitRequest">{{saving?'Submitting…':'Submit request'}}</ion-button></section></div>
  </ion-page>
</template>

<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {IonButton,IonContent,IonIcon,IonPage,IonSearchbar} from '@ionic/vue';
import {readSheet as readXlsxFile} from 'read-excel-file/browser';
import type {Row} from 'read-excel-file/browser';
import {addCircleOutline,bagHandleOutline,checkmarkCircleOutline,chevronDownOutline,cubeOutline,documentOutline,documentTextOutline,logOutOutline,menuOutline,notificationsOutline,peopleOutline,personCircleOutline,settingsOutline,shieldCheckmarkOutline,shirtOutline,timeOutline} from 'ionicons/icons';
import {portal} from '../stores/portal';
import type {Product,RequestItem,RequestStatus,Role,UniformRequest} from '../app/models';
import RequestTable from '../components/RequestTable.vue';

const route=useRoute(),router=useRouter();
const role=computed(()=>route.params.role as Role),section=computed(()=>String(route.params.section||'dashboard'));
const navOpen=ref(false),accountMenuOpen=ref(false),busy=ref(false),saving=ref(false),message=ref(''),messageType=ref('success'),search=ref(''),status=ref(''),studentSearch=ref(''),selectedRequest=ref<UniformRequest|null>(null),inventoryOpen=ref(false),cartOpen=ref(false),fileInput=ref<HTMLInputElement|null>(null),currentPassword=ref(''),newPassword=ref(''),confirmPassword=ref('');
const chosen=reactive<Record<string,string>>({}),cart=ref<RequestItem[]>([]),profile=reactive({name:'',identifier:'',email:'',phone:'',program:'',year:''}),inventory=reactive({productId:'',name:'',category:'',description:'',size:'',stock:0});
const inviteHours=ref(24),studentInviteLink=ref(''),staffInviteLink=ref('');
const studentMenu=[{path:'dashboard',label:'Dashboard',icon:cubeOutline},{path:'catalog',label:'Request Uniform',icon:shirtOutline},{path:'requests',label:'My Requests',icon:documentTextOutline}];
const marketingMenu=[{path:'dashboard',label:'Dashboard',icon:cubeOutline},{path:'requests',label:'Manage Requests',icon:documentTextOutline},{path:'students',label:'Student Directory',icon:peopleOutline},{path:'inventory',label:'Inventory',icon:cubeOutline},{path:'staff',label:'Staff Invitations',icon:peopleOutline}];
const menu=computed(()=>role.value==='marketing'?marketingMenu:studentMenu),pageTitle=computed(()=>section.value==='profile'?'Profile':section.value==='settings'?'Settings':menu.value.find(x=>x.path===section.value)?.label||'UniformHub'),firstName=computed(()=>portal.user.value?.name?.split(' ')[0]||'User'),initials=computed(()=>portal.user.value?.name?.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()||'UH');
const statuses:RequestStatus[]=['Pending','Under Review','Approved','Rejected','Preparing','Ready for Pickup','Completed','Cancelled'];
const pendingCount=computed(()=>portal.requests.value.filter(x=>['Pending','Under Review','Approved','Preparing'].includes(x.status)).length),readyCount=computed(()=>portal.requests.value.filter(x=>['Ready for Pickup','Completed'].includes(x.status)).length),totalStock=computed(()=>portal.products.value.flatMap(x=>x.sizes).reduce((n,x)=>n+x.stock,0));
const filteredRequests=computed(()=>portal.requests.value.filter(x=>(!status.value||x.status===status.value)&&(!search.value||`${x.reference} ${x.studentName} ${x.studentId}`.toLowerCase().includes(search.value.toLowerCase()))));
const filteredStudents=computed(()=>portal.students.value.filter(x=>!studentSearch.value||`${x.fullName} ${x.studentId} ${x.phinmaEmail}`.toLowerCase().includes(studentSearch.value.toLowerCase())));
const marketingInvites=computed(()=>portal.invitations.value.filter(invite=>invite.role==='marketing'));
const studentInvites=computed(()=>portal.invitations.value.filter(invite=>invite.role==='student'));
function flash(text:string,type='success'){message.value=text;messageType.value=type;window.setTimeout(()=>message.value='',5000)}
function statusCount(value:RequestStatus){return portal.requests.value.filter(request=>request.status===value).length}
function syncProfile(){const u=portal.user.value;if(u)Object.assign(profile,{name:u.name,identifier:u.identifier,email:u.email||'',phone:u.phone||'',program:u.program||'',year:u.year||''})}
async function load(){busy.value=true;try{await portal.load();if(role.value==='marketing'&&['staff','students'].includes(section.value))await portal.loadInvitations();syncProfile()}catch(e){flash(errorText(e),'error')}finally{busy.value=false}}
onMounted(load);watch(()=>route.fullPath,async()=>{navOpen.value=false;accountMenuOpen.value=false;if(role.value==='marketing'&&['staff','students'].includes(section.value))try{await portal.loadInvitations()}catch(e){flash(errorText(e),'error')}});
async function logout(){const loginRole=role.value;accountMenuOpen.value=false;try{await portal.logout()}finally{await router.replace(`/${loginRole}/login`)}}
function addToCart(p:Product){const size=p.sizes.find(x=>x.id===chosen[p.id]);if(!size)return;const existing=cart.value.find(x=>x.sizeId===size.id);if(existing)existing.quantity++;else cart.value.push({productId:p.id,productName:p.name,sizeId:size.id,size:size.label,quantity:1,unitPrice:0});flash(`${p.name} (${size.label}) added to your request.`)}
async function submitRequest(){saving.value=true;try{await portal.submitRequest(cart.value);cart.value=[];cartOpen.value=false;flash('Your uniform request was submitted.');await router.push(`/${role.value}/requests`)}catch(e){flash(errorText(e),'error')}finally{saving.value=false}}
function nextStatuses(current:RequestStatus):RequestStatus[]{const flow:Record<string,RequestStatus[]>={Pending:['Under Review','Rejected'], 'Under Review':['Approved','Rejected'],Approved:['Preparing'],Preparing:['Ready for Pickup'],'Ready for Pickup':['Completed']};return flow[current]||[]}
async function setStatus(next:RequestStatus){if(!selectedRequest.value)return;saving.value=true;try{await portal.updateStatus(selectedRequest.value.id,next);selectedRequest.value=null;flash(`Request moved to ${next}.`)}catch(e){flash(errorText(e),'error')}finally{saving.value=false}}
function openInventory(p?:Product){Object.assign(inventory,{productId:p?.id||'',name:p?.name||'',category:p?.category||'',description:p?.description||'',size:'',stock:0});inventoryOpen.value=true}
function pickProduct(){const p=portal.products.value.find(x=>x.id===inventory.productId);if(p)Object.assign(inventory,{name:p.name,category:p.category,description:p.description})}
async function saveInventory(){saving.value=true;try{await portal.createInventory({...inventory});inventoryOpen.value=false;flash('Inventory saved successfully.')}catch(e){flash(errorText(e),'error')}finally{saving.value=false}}
async function changeStock(id:string,delta:number){try{await portal.adjustStock(id,delta)}catch(e){flash(errorText(e),'error')}}
async function saveProfile(){saving.value=true;try{await portal.updateProfile(profile);syncProfile();flash('Profile updated.')}catch(e){flash(errorText(e),'error')}finally{saving.value=false}}
async function savePassword(){if(newPassword.value!==confirmPassword.value){flash('Passwords do not match.','error');return}if(currentPassword.value===newPassword.value){flash('Choose a new password that is different from your current password.','error');return}saving.value=true;try{await portal.updatePassword(currentPassword.value,newPassword.value);currentPassword.value='';newPassword.value='';confirmPassword.value='';flash('Password updated successfully.')}catch(e){flash(errorText(e),'error')}finally{saving.value=false}}
async function generateInvite(inviteRole:Role){saving.value=true;try{const result=await portal.createRegistrationInvitation(inviteRole,inviteHours.value);if(inviteRole==='student')studentInviteLink.value=result.url;else staffInviteLink.value=result.url;flash(`${inviteRole==='student'?'Student':'Staff'} registration link generated.`)}catch(e){flash(errorText(e),'error')}finally{saving.value=false}}
async function copyInvite(link:string){try{await navigator.clipboard.writeText(link);flash('Invitation link copied.')}catch{flash('Copy failed. Select the link and copy it manually.','error')}}
async function revokeInvitation(id:string){try{await portal.revokeRegistrationInvitation(id);flash('Invitation revoked.')}catch(e){flash(errorText(e),'error')}}
async function deleteInvitation(id:string){try{await portal.deleteRegistrationInvitation(id);flash('Invitation removed.')}catch(e){flash(errorText(e),'error')}}
function inviteStatus(invite:{revokedAt?:string;expiresAt:string}){if(invite.revokedAt)return'Revoked';if(new Date(invite.expiresAt)<=new Date())return'Expired';return'Active'}
function formatInviteDate(value:string){return new Intl.DateTimeFormat('en-PH',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
async function importExcel(event:Event){
  const input=event.target as HTMLInputElement,file=input.files?.[0];
  if(!file)return;
  try{
    const rows:Row[]=await readXlsxFile(file);
    if(rows.length<2)throw new Error('The Excel file has no student rows.');
    const normalize=(value:unknown)=>String(value??'').replace(/^\uFEFF/,'').trim().toLowerCase().replace(/[_-]+/g,' ').replace(/\s+/g,' ');
    const required=['student id','full name'];
    const headerRowIndex=rows.findIndex(row=>{
      const cells=row.map(normalize);
      return required.every(name=>cells.includes(name))&&cells.some(name=>['phinma email','email','email address','phinma email address'].includes(name));
    });
    if(headerRowIndex<0)throw new Error('Could not find the header row. Required columns are Student ID, Full Name, and PHINMA Email.');
    const headers=rows[headerRowIndex].map(normalize);
    const find=(...names:string[])=>headers.findIndex(header=>names.includes(header));
    const indexes={
      studentId:find('student id','student number','id number'),
      fullName:find('full name','student name','student','name'),
      email:find('phinma email','email','email address','phinma email address'),
      program:find('program','course','degree program'),
      year:find('year','year level','level')
    };
    const data=rows.slice(headerRowIndex+1).filter(row=>row.some(cell=>String(cell??'').trim())).map(row=>({
      studentId:String(row[indexes.studentId]??'').trim(),
      fullName:String(row[indexes.fullName]??'').trim(),
      email:String(row[indexes.email]??'').trim(),
      program:indexes.program>=0?String(row[indexes.program]??'').trim():'',
      yearLevel:indexes.year>=0?String(row[indexes.year]??'').trim():''
    })).filter(row=>row.studentId&&row.fullName&&row.email);
    if(!data.length)throw new Error('No complete student records were found below the header row.');
    const count=portal.importStudents(data);
    flash(`Imported ${count} student record(s). They are now displayed in the directory.`);
  }catch(e){flash(errorText(e),'error')}finally{input.value=''}
}
function printReport(){window.print()}
function errorText(e:unknown){if(e instanceof Error)return e.message;if(e&&typeof e==='object'&&'message' in e&&typeof e.message==='string')return e.message;return'Something went wrong. Please try again.'}
